// First-load round (docs/design/first-load.md). A generated table and a budget.
//
// 1. sw.js's VERSIONS table is generated by scripts/startup-graph.mjs. A ?v= bump
//    without re-running it would make the worker precache (and answer with) an old copy.
// 2. The startup graph (what main.js reaches by STATIC imports) is everything a phone
//    downloads and parses before the chat list shows. It may not grow unnoticed:
//    a new feature that is not needed for the first screen belongs behind import().
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { gzipSync } from 'node:zlib';
import { STATIC, startupGraph, stale } from '../scripts/startup-graph.mjs';

// Measured 2026-11-19 at 71 modules, 1.89 MB raw, 0.62 MB gzip (main.js included).
// Raise only with a reason in docs/design/first-load.md.
const BUDGET = { modules: 72, rawBytes: 1_950_000, gzipBytes: 640_000 };

test('the generated version table is up to date', () => {
  assert.deepEqual(stale(), [], 'run: node frontend/scripts/startup-graph.mjs');
});

test('the startup module graph stays inside its budget', () => {
  const files = ['/static/js/main.js', ...startupGraph().map((m) => m.path)];
  let raw = 0;
  let gz = 0;
  for (const p of files) {
    const abs = join(STATIC, p.replace(/^\/static\//, ''));
    raw += statSync(abs).size;
    gz += gzipSync(readFileSync(abs), { level: 6 }).length;
  }
  const msg = `startup graph: ${files.length} modules, ${raw} B raw, ${gz} B gzip; budget ${JSON.stringify(BUDGET)}`;
  assert.ok(files.length <= BUDGET.modules, msg);
  assert.ok(raw <= BUDGET.rawBytes, msg);
  assert.ok(gz <= BUDGET.gzipBytes, msg);
});

test('the worker answers only the version it precached from its cache', () => {
  const sw = readFileSync(join(STATIC, 'sw.js'), 'utf8');
  assert.match(sw, /if \(pinned && VERSIONS\[p\] === v\)/);
  // Another version is never written under the bare path (an older tab would get it).
  assert.match(sw, /if \(res\.ok && !pinned\)/);
});

test('index.html does not modulepreload the whole graph (measured: slower warm opens)', () => {
  const html = readFileSync(join(STATIC, 'index.html'), 'utf8');
  const n = [...html.matchAll(/rel="modulepreload"/g)].length;
  assert.ok(n <= 3, `${n} modulepreload links`);
});

test('the worker precaches at the page URL, revalidated, never with cache: reload', () => {
  const sw = readFileSync(join(STATIC, 'sw.js'), 'utf8');
  // The page's own URL (a 304 against the copy it just fetched), always revalidated.
  assert.match(sw, /new Request\(v \? `\$\{path\}\?v=\$\{v\}` : path, \{ cache: 'no-cache' \}\)/);
  assert.doesNotMatch(sw, /\{ cache: 'reload' \}/);
  // Stored under the bare path: the key the fetch handler reads for the offline fallback.
  assert.match(sw, /c\.put\(path, res\)/);
});

test('the worker registers after boot, not during parsing', () => {
  const html = readFileSync(join(STATIC, 'index.html'), 'utf8');
  const i = html.indexOf("navigator.serviceWorker.register('/static/sw.js'");
  const j = html.indexOf('whenBooted(() => {');
  assert.ok(j > 0 && j < i, 'register() must run inside whenBooted()');
  assert.match(html, /window\.__bootDone \|\| Date\.now\(\) - t0 > 20000/);
  // Privacy mode switched on during boot still keeps the worker out.
  assert.ok(html.indexOf("localStorage.getItem('dispatch-privacy') === '1') return;") > j);
});
